SELECT * INTO v_insumo FROM insumos
  WHERE id = NEW.insumo_id FOR UPDATE;  -- trava a linha

IF NEW.type = &#x27;IN&#x27; THEN
  v_new_qty := v_insumo.current_stock + NEW.quantity;
  v_new_cost := (v_insumo.current_stock * v_insumo.average_unit_cost
               + NEW.quantity * NEW.unit_cost) / v_new_qty;
ELSIF NEW.type = &#x27;OUT&#x27; THEN
  v_new_qty := v_insumo.current_stock - NEW.quantity;
  NEW.unit_cost := v_insumo.average_unit_cost;
END IF;

